krb5_error_code krb5kdc_check_valid_kdcPkId(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx, pkinit_req_crypto_context req_cryptoctx, pkinit_identity_crypto_context id_cryptoctx, unsigned char *pdid_buf, unsigned int pkid_len, int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    krb5_data pdid_data;
    krb5_principal kdc_princ = NULL;
    krb5_principal client_princ = NULL;
    krb5_keytab keytab = NULL;
    krb5_kt_cursor cursor;
    krb5_keytab_entry entry;
    int found = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pkid_len;

    *valid_kdcPkId = 0;

    if ((retval = krb5_kt_default(context, &keytab)) != 0)
        goto out;

    if ((retval = krb5_parse_name(context, "KDC_FQDN", &kdc_princ)) != 0)
        goto out;

    while (!found && krb5_kt_next_entry(context, keytab, &entry, &cursor)) {
        if (krb5_principal_compare(context, entry.principal, kdc_princ) == 1) {
            // Match found, check validity based on cert issuer and serial number
            *valid_kdcPkId = 1;
            found = 1;
        }
        krb5_kt_free_entry(context, &entry);
    }

    if (!found) {
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
    }

out:
    if (kdc_princ)
        krb5_free_principal(context, kdc_princ);
    if (keytab)
        krb5_kt_close(context, keytab);

    return retval;
}

krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                                pkinit_plg_crypto_context plg_cryptoctx,
                                                pkinit_req_crypto_context req_cryptoctx,
                                                pkinit_identity_crypto_context id_cryptoctx,
                                                unsigned char *pdid_buf,
                                                unsigned int pdid_len,
                                                int *valid_kdcPkId) {
    krb5_error_code ret = 0;
    krb5_data pdid_data;
    pkinit_pkeyid pkeyid = {0};
    krb5_principal kdc_princ = NULL;
    krb5_principal issuer = NULL;
    krb5_cert_info cert_info = {0};
    krb5_boolean match = FALSE;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pdid_len;

    ret = decode_pkinit_pkeyid(&pdid_data, &pkeyid);
    if (ret != 0) {
        ret = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    ret = krb5_build_principal(context, &kdc_princ, 0, NULL, 0, NULL);
    if (ret != 0) {
        goto cleanup;
    }

    issuer = pkeyid.issuer;
    if (!issuer || issuer->length == 0) {
        ret = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    cert_info.issuer = issuer;
    cert_info.serial_number = pkeyid.serial;

    ret = krb5_cert_compare_cert_info(context, id_cryptoctx->kdc_cert, &cert_info, &match);
    if (ret != 0) {
        goto cleanup;
    }

    if (match) {
        *valid_kdcPkId = 1;
    } else {
        ret = KRB5KDC_ERR_PREAUTH_FAILED;
    }

cleanup:
    if (pkeyid.issuer) {
        krb5_free_principal(context, pkeyid.issuer);
    }
    if (kdc_princ) {
        krb5_free_principal(context, kdc_princ);
    }

    return ret;
}

krb5_error_code check_valid_kdcPkId(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx,
                                    pkinit_req_crypto_context req_cryptoctx,
                                    pkinit_identity_crypto_context id_cryptoctx,
                                    unsigned char *pdid_buf, unsigned int pdid_len,
                                    int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    krb5_data pdid_data;
    pkinit_pkeyid pkeyid = NULL;
    krb5_principal kdc_princ = NULL;
    krb5_principal issuer = NULL;
    krb5_cert_issuer issuer_info;
    krb5_principal current_principal = NULL;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pdid_len;

    if ((retval = pkinit_decode_PKINIT_PKEYID(context, &pdid_data, &pkeyid))) {
        goto out;
    }

    if ((retval = krb5_krb_to_kdc_princ(context, 0, plg_cryptoctx->kdc_realm, &kdc_princ))) {
        goto out;
    }

    issuer_info.issuer = pkeyid->issuer;
    issuer_info.issuer_len = pkeyid->issuer_len;
    issuer_info.serial_number = pkeyid->serial_number;
    issuer_info.serial_number_len = pkeyid->serial_number_len;

    if ((retval = krb5_build_principal_simple(context, &issuer, issuer_info.issuer_len, issuer_info.issuer))) {
        goto out;
    }

    if ((retval = krb5_kdc_get_principal(context, kdc_princ, &current_principal, 0))) {
        goto out;
    }

    if ((retval = krb5_cert_compare_issuer(context, current_principal, &issuer_info))) {
        goto out;
    }

    *valid_kdcPkId = 1;

out:
    if (pkeyid) {
        pkinit_free_PKINIT_PKEYID(context, pkeyid);
    }
    if (kdc_princ) {
        krb5_free_principal(context, kdc_princ);
    }
    if (issuer) {
        krb5_free_principal(context, issuer);
    }
    if (current_principal) {
        krb5_free_principal(context, current_principal);
    }

    if (retval) {
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    return 0;
}

krb5_error_code validate_kdc_public_key_identifier(krb5_context context,
                                                   pkinit_plg_crypto_context plg_cryptoctx,
                                                   pkinit_req_crypto_context req_cryptoctx,
                                                   pkinit_identity_crypto_context id_cryptoctx,
                                                   unsigned char *pdid_buf,
                                                   unsigned int pdid_len,
                                                   int *valid_kdcPkId) {
    krb5_error_code retval = 0;
    pkinit_padata padata = NULL;
    krb5_principal kdc_principal = NULL;
    krb5_data *decoded = NULL;
    krb5_principal issuer = NULL;
    krb5_crypto_keyblock *keyblock = NULL;

    if (valid_kdcPkId == NULL) {
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    *valid_kdcPkId = 0;

    retval = pkinit_decode_padata(context, pdid_buf, pdid_len, &padata);
    if (retval) {
        goto cleanup;
    }

    /* Extract KDC's certificate from id_cryptoctx */
    if (id_cryptoctx->kdc_cert == NULL) {
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    /* Extract issuer and serial number from certificate */
    issuer = krb5_X509_get_issuer(context, id_cryptoctx->kdc_cert);
    if (issuer == NULL) {
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    /* Compare with certificate issuer and serial number in padata */
    if (id_cryptoctx->kdc_cert->issuer == NULL || id_cryptoctx->kdc_cert->serial == NULL) {
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    if (!krb5_principal_compare(context, issuer, padata->issuer)) {
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    if (padata->serial != id_cryptoctx->kdc_cert->serial->data) {
        retval = KRB5KDC_ERR_PREAUTH_FAILED;
        goto cleanup;
    }

    *valid_kdcPkId = 1;

cleanup:
    if (padata) {
        free_padata(context, padata);
    }
    if (issuer) {
        krb5_principal_free(context, issuer);
    }
    if (keyblock) {
        krb5_free_keyblock(context, keyblock);
    }
    if (kdc_principal) {
        krb5_free_principal(context, kdc_principal);
    }

    return retval;
}

krb5_error_code check_kdc_public_key_identifier(krb5_context context,
                                                pkinit_plg_crypto_context plg_cryptoctx,
                                                pkinit_req_crypto_context req_cryptoctx,
                                                pkinit_identity_crypto_context id_cryptoctx,
                                                unsigned char *pdid_buf,
                                                unsigned int pdid_len,
                                                int *valid_kdcPkId) {
    krb5_error_code kret = 0;
    krb5_data pdid_data;
    krb5_principal kdc_princ = NULL;
    krb5_principal req_princ = NULL;
    krb5_principal id_princ = NULL;
    krb5_cert_info *cert_info = NULL;

    *valid_kdcPkId = 0;

    pdid_data.data = (char *)pdid_buf;
    pdid_data.length = pdid_len;

    kret = krb5_pkinit_decode_kdc_pkid(context, &pdid_data, &kdc_princ, NULL, NULL);
    if (kret != 0) {
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    kret = krb5_build_principal(context, &req_princ, req_cryptoctx->realm,
                                req_cryptoctx->realm->length, req_cryptoctx->realm->data, NULL);
    if (kret != 0) {
        krb5_free_principal(context, kdc_princ);
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    kret = krb5_build_principal(context, &id_princ, id_cryptoctx->realm,
                                id_cryptoctx->realm->length, id_cryptoctx->realm->data, NULL);
    if (kret != 0) {
        krb5_free_principal(context, kdc_princ);
        krb5_free_principal(context, req_princ);
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    kret = krb5_cert_get_subject(context, plg_cryptoctx->kdc_cert, &cert_info);
    if (kret != 0) {
        krb5_free_principal(context, kdc_princ);
        krb5_free_principal(context, req_princ);
        krb5_free_principal(context, id_princ);
        return KRB5KDC_ERR_PREAUTH_FAILED;
    }

    if (krb5_principal_compare(context, cert_info->subject, kdc_princ) != 0 ||
        krb5_principal_compare(context, cert_info->subject, req_princ) != 0 ||
        krb5_principal_compare(context, cert_info->subject, id_princ) != 0) {
        kret = KRB5KDC_ERR_PREAUTH_FAILED;
    } else {
        *valid_kdcPkId = 1;
    }

    krb5_free_principal(context, kdc_princ);
    krb5_free_principal(context, req_princ);
    krb5_free_principal(context, id_princ);
    krb5_cert_info_free(context, cert_info);

    return kret;
}
